import{_ as o,o as d,c,a2 as t}from"./chunks/framework.CCXDMzJr.js";const g=JSON.parse('{"title":"第 15 章 能力接缝：执行与沙箱","description":"","frontmatter":{},"headers":[],"relativePath":"ch15-capability-seams.md","filePath":"ch15-capability-seams.md","lastUpdated":1786693096000}'),a={name:"ch15-capability-seams.md"};function s(r,e,l,i,n,p){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="第-15-章-能力接缝-执行与沙箱" tabindex="-1">第 15 章 能力接缝：执行与沙箱 <a class="header-anchor" href="#第-15-章-能力接缝-执行与沙箱" aria-label="Permalink to &quot;第 15 章 能力接缝：执行与沙箱&quot;">​</a></h1><p>本章解剖 dsh 的&quot;执行家族&quot;：文件系统、沙箱、子进程、shell、终端、后台作业、审批。它们共同构成&quot;抽象接缝 → 本地实现 → 模型工具消费&quot;的分层家族——<strong>Definition 只声明能力与边界，Provider 拥有执行世界，Consumer 负责把 per-call 策略交给能力并渲染结果</strong>。一次 Provider 替换，整个产品随之迁移。</p><h2 id="_15-1-家族总览" tabindex="-1">15.1 家族总览 <a class="header-anchor" href="#_15-1-家族总览" aria-label="Permalink to &quot;15.1 家族总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ctx 服务</th><th>角色</th><th>Definition</th><th>Provider(s)</th><th>主要 Consumer</th></tr></thead><tbody><tr><td><code>ctx.fs</code></td><td>seam</td><td><code>packages/fs/fs</code></td><td><code>fs-local</code>、<code>fs-sandbox</code>、<code>fs-e2b</code></td><td><code>tool-fs</code></td></tr><tr><td><code>ctx.sandbox</code></td><td>seam</td><td><code>packages/sandbox/sandbox</code></td><td><code>sandbox-local</code>、<code>sandbox-windows-acl</code></td><td><code>bash-sandbox</code>、<code>terminal-bash</code></td></tr><tr><td><code>ctx.sandboxPolicy</code></td><td>core</td><td><code>sandbox-policy</code></td><td>—</td><td>两个强制族共用</td></tr><tr><td><code>ctx.subprocess</code></td><td>seam</td><td><code>packages/subprocess/subprocess</code></td><td><code>subprocess-local</code>、<code>subprocess-e2b</code></td><td><code>bash-*</code>、LSP、子代理</td></tr><tr><td><code>ctx.shell</code></td><td>seam</td><td><code>packages/shell/shell</code></td><td><code>bash-local</code>、<code>bash-sandbox</code>、<code>pwsh-local</code></td><td><code>tool-bash</code></td></tr><tr><td><code>ctx.terminals</code></td><td>seam</td><td><code>packages/terminal/terminal</code></td><td><code>terminal-bash</code></td><td><code>tool-terminal</code></td></tr><tr><td><code>ctx.jobs</code></td><td>seam</td><td><code>packages/jobs/jobs</code></td><td><code>jobs-local</code></td><td><code>tool-jobs</code>、<code>tool-bash</code>(bg)</td></tr><tr><td><code>ctx.codeRuntime</code></td><td>seam</td><td><code>packages/code-runtime/code-runtime</code></td><td><code>code-runtime-worker</code></td><td>Code Mode</td></tr><tr><td><code>ctx.storage</code></td><td>seam</td><td><code>packages/storage/storage</code></td><td><code>storage-json</code>、<code>storage-sqlite</code></td><td>各持久化域</td></tr><tr><td><code>ctx.attachments</code> / <code>ctx.credentials</code></td><td>seam</td><td><code>attachment</code> / <code>credentials</code></td><td><code>attachment-local</code> / <code>credentials-local</code></td><td>LLM 适配器</td></tr><tr><td><code>ctx.approval</code></td><td>seam</td><td><code>interaction/user-approval</code></td><td><code>acp</code>(桥)</td><td><code>tools</code>、<code>tool-bash</code>、<code>tool-fs</code></td></tr></tbody></table><p><strong>接缝语义设计核心</strong>：多个同族 Provider（本地/沙箱/远程 e2b）通过&quot;一次只装一个对应 ctx 服务的实现&quot;热切换，工具层与策略层不感知后端差异——这是全书最值得强调的架构主线之一。</p><h2 id="_15-2-通用语言-结构化错误与品牌化-id" tabindex="-1">15.2 通用语言：结构化错误与品牌化 ID <a class="header-anchor" href="#_15-2-通用语言-结构化错误与品牌化-id" aria-label="Permalink to &quot;15.2 通用语言：结构化错误与品牌化 ID&quot;">​</a></h2><ul><li><strong><code>HarnessError</code></strong>（<code>@deepseek-ai/dsh-llm</code>）：所有能力错误的基类，带 <code>code</code> 字段；工具注册表把 <code>{ name, code }</code> 原样放进 <code>isError</code> 结果——重试/权限/UI 层不看消息文本直接分支；</li><li><strong>品牌化 ID</strong>：<code>FsTargetKey</code>/<code>FsVersion</code>、<code>ApprovalRequestId</code>、<code>JobId</code>——&quot;包装成类型但不做输入校验&quot;的字符串。官方注释强调：消费方<strong>不得解析</strong> targetKey、<strong>不得解释</strong> version——接缝把&quot;宿主路径&quot;与&quot;执行世界路径&quot;二元划分。</li></ul><h2 id="_15-3-ctx-fs-文件系统接缝" tabindex="-1">15.3 ctx.fs：文件系统接缝 <a class="header-anchor" href="#_15-3-ctx-fs-文件系统接缝" aria-label="Permalink to &quot;15.3 ctx.fs：文件系统接缝&quot;">​</a></h2><h3 id="definition-packages-fs-fs-src-index-ts" tabindex="-1">Definition（<code>packages/fs/fs/src/index.ts</code>） <a class="header-anchor" href="#definition-packages-fs-fs-src-index-ts" aria-label="Permalink to &quot;Definition（`packages/fs/fs/src/index.ts`）&quot;">​</a></h3><ul><li><code>resolve(path, opts)</code> → <code>FsTarget</code>：把用户/模型路径解析成该执行世界的稳定目标（local 后端 normalize+realpath；远程后端可能一次回环，故设计为 async）；</li><li><code>processPath(target)</code> / <code>fileUrl(target)</code>：返回&quot;本执行世界内子进程能打开 / 真正的 file: URI&quot;——与不透明的 <code>targetKey</code> 区分，消费方可把 <code>processPath</code> 传给另一个 OS 能力；</li><li><code>contains(parent, child)</code>：规范包含判定；</li><li><code>stat</code>/<code>lstat</code>：<code>lstat</code> 不 follow 最终 symlink，能报 <code>symlink</code> 供信任边界拒绝；</li><li><code>readText</code>/<code>streamText</code>/<code>readBytes</code>：字节读取<strong>必带 <code>maxBytes</code> 上限</strong>，超限报 <code>FS_TOO_LARGE</code> 而非无界缓冲；</li><li><code>writeText</code>/<code>editText</code>：<strong>原子</strong>写/字面编辑，可选版本守卫（<code>expected</code>），可带 <code>sandboxPolicy</code>（per-call 沙箱策略）；</li><li><code>sandboxMode</code> getter：后端&quot;默认是否自带沙箱&quot;的能力事实（<code>fs-sandbox</code> 覆写为部署默认）。</li></ul><h3 id="provider-对比" tabindex="-1">Provider 对比 <a class="header-anchor" href="#provider-对比" aria-label="Permalink to &quot;Provider 对比&quot;">​</a></h3><ul><li><strong><code>fs-local</code></strong>：朴素本地实现，直通 OS；</li><li><strong><code>fs-sandbox</code></strong>：沙箱栅栏——每个操作经 <code>ctx.sandbox.confine</code> 包裹后再执行；</li><li><strong><code>fs-e2b</code></strong>：远程执行世界（E2B 沙箱）。</li></ul><h3 id="伴生策略-fs-observation-policy" tabindex="-1">伴生策略：fs-observation-policy <a class="header-anchor" href="#伴生策略-fs-observation-policy" aria-label="Permalink to &quot;伴生策略：fs-observation-policy&quot;">​</a></h3><p><code>fs/*</code> 事件（<code>fs/observed</code>、<code>fs/write-intent</code> 等）携带<strong>不透明的 actor 对象</strong>（<code>ToolExecution</code>），策略插件结构性窄化（<code>actor.agent.session</code> 作 owner）。文件操作被观察、被策略过滤，工具本身不内置策略。</p><h2 id="_15-4-ctx-sandbox-沙箱接缝" tabindex="-1">15.4 ctx.sandbox：沙箱接缝 <a class="header-anchor" href="#_15-4-ctx-sandbox-沙箱接缝" aria-label="Permalink to &quot;15.4 ctx.sandbox：沙箱接缝&quot;">​</a></h2><h3 id="definition-packages-sandbox-sandbox-src-index-ts" tabindex="-1">Definition（<code>packages/sandbox/sandbox/src/index.ts</code>） <a class="header-anchor" href="#definition-packages-sandbox-sandbox-src-index-ts" aria-label="Permalink to &quot;Definition（`packages/sandbox/sandbox/src/index.ts`）&quot;">​</a></h3><p>唯一抽象方法：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">abstract </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">confine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(argv: readonly string[], policy: SandboxPolicy): ConfinedArgv</span></span></code></pre></div><ul><li><strong>语义</strong>：把&quot;将要 spawn 的确切 argv&quot;包成受某个 host-path 文件策略的执行。容器/microVM/远程执行是&quot;替换整条能力接缝&quot;的兄弟实现，<strong>不是</strong> <code>ctx.sandbox</code> 的 provider；</li><li><strong>per-call 策略</strong>：<code>SandboxMode = &#39;read-only&#39; | &#39;workspace-write&#39; | &#39;danger-full-access&#39;</code>，策略随调用携带——同一时刻两个消费方可要求不同边界（bash 只读、子代理可写状态目录）；已批准的升级重试就是带更宽策略的新调用。<code>danger-full-access</code> 消费方直接 spawn 原始 argv，不调用 <code>ctx.sandbox</code>；</li><li><strong><code>ConfinedArgv</code></strong>：替换 argv + enforcement（<code>full | partial</code>）+ 该后端私有的 denial 方言（bwrap 报 EROFS、Landlock 报 EACCES、Seatbelt 报 EPERM）+ runner 失败规则；</li><li><strong>失败关闭</strong>：没有可用后端时抛 <code>SandboxUnavailableError</code>（<code>SANDBOX_UNAVAILABLE</code>），<strong>绝不允许静默非受控放行</strong>。</li></ul><h3 id="升级编排-escalation-ts" tabindex="-1">升级编排：escalation.ts <a class="header-anchor" href="#升级编排-escalation-ts" aria-label="Permalink to &quot;升级编排：escalation.ts&quot;">​</a></h3><p>bash/fs 两个强制族共用的&quot;升级编舞&quot;：</p><ul><li><code>WIDER_MODES</code>：<code>read-only → [workspace-write, danger-full-access]</code> 严格更宽阶梯——<strong>执行期检查，绝不烘进工具 schema</strong>；</li><li><code>validateEscalationArgs</code>：<code>sandbox_permissions</code> 与 <code>justification</code> 必须成对、理由为非空句子；</li><li>统一模型可见词汇：<code>[sandbox: file access denied under ${mode} mode]</code> 与 <code>[sandbox: escalation available — retry this exact ${subject} once …]</code>；</li><li><code>approveEscalation</code>：执行前失败关闭序列——先判严格更宽（不更宽绝不提示人），再查 approval/agent，然后 <code>approval.approver.request(...)</code>，把 <code>allowed-once</code> 印到这一次调用。<code>EscalationApprover</code> 是<strong>结构性闭包</strong>而非 approval 服务类型——本包不依赖 approval/agent 包。</li></ul><h3 id="策略唯一归属-ctx-sandboxpolicy" tabindex="-1">策略唯一归属：ctx.sandboxPolicy <a class="header-anchor" href="#策略唯一归属-ctx-sandboxpolicy" aria-label="Permalink to &quot;策略唯一归属：ctx.sandboxPolicy&quot;">​</a></h3><p><code>SandboxPolicyService</code> 是&quot;部署默认 mode + workspace-write 根 + per-session 解析&quot;的唯一主人：</p><ul><li>默认 <code>mode: &#39;read-only&#39;</code>（<strong>失败安全默认</strong>，要可写须显式 opt-in）；</li><li><code>resolve()</code> 优先级：已批准显式 mode &gt; session 日志最后一条 <code>sandbox/mode</code> 事件的 fold &gt; 部署默认；<code>workspaceRoot</code> 取 <code>session.header.cwd</code>（session 不可变 cwd 即工作区边界）；</li><li>host-path canonicalize 先于词法归一（<code>realpathSync.native</code>——<code>/tmp</code> 在 darwin 是 <code>/private/tmp</code> 这类陷阱）；</li><li>per-session 覆盖是<strong>持久化会话事件</strong>（<code>sandbox/mode</code>，log-only 可重放），<code>setSandboxMode</code> 是唯一写路径；</li><li>向 <code>systemPrompt</code> 注入 <code>sandbox:policy</code> 运行时上下文段落，把当前 mode/根描述进模型历史。</li></ul><h3 id="sandbox-local-平台-runner-链" tabindex="-1">sandbox-local：平台 runner 链 <a class="header-anchor" href="#sandbox-local-平台-runner-链" aria-label="Permalink to &quot;sandbox-local：平台 runner 链&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PLATFORM_CHAINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { linux: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;bwrap&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;landlock&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], darwin: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;seatbelt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], win32: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;windows-acl&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><ul><li>bwrap 只读 profile：<code>[&#39;--ro-bind&#39;,&#39;/&#39;,&#39;/&#39;,&#39;--dev&#39;,&#39;/dev&#39;,&#39;--proc&#39;,&#39;/proc&#39;,&#39;--die-with-parent&#39;]</code>，workspace-write 追加 <code>--tmpfs /tmp</code> + <code>--bind workspaceRoot</code>；</li><li>功能探测仲裁：单一候选免探测；多候选按链序 <code>probeRunner</code>（bwrap exit 0 → full；seatbelt <code>sandbox-exec -p &lt;read-only profile&gt; -- true</code>…），探测预算默认 5000ms；无可用 runner <strong>fail-closed</strong> 抛 <code>SandboxUnavailableError</code>；</li><li>Windows：<code>CreateRestrictedToken</code>（<code>DISABLE_MAX_PRIVILEGE|LUA_TOKEN|WRITE_RESTRICTED</code>）+ restricting SIDs + per-path 排他锁 + 每次调用派生 logon SID，fail-closed，绝不无限制 spawn。</li></ul><h2 id="_15-5-审批-ctx-approval" tabindex="-1">15.5 审批：ctx.approval <a class="header-anchor" href="#_15-5-审批-ctx-approval" aria-label="Permalink to &quot;15.5 审批：ctx.approval&quot;">​</a></h2><h3 id="definition-packages-interaction-user-approval-src-index-ts" tabindex="-1">Definition（<code>packages/interaction/user-approval/src/index.ts</code>） <a class="header-anchor" href="#definition-packages-interaction-user-approval-src-index-ts" aria-label="Permalink to &quot;Definition（`packages/interaction/user-approval/src/index.ts`）&quot;">​</a></h3><ul><li><code>ApprovalOutcome = &#39;allowed-once&#39; | &#39;rejected&#39; | &#39;cancelled&#39; | &#39;unavailable&#39;</code>——闭合、失败关闭；<code>allowed-once</code> 是唯一授予，只授予被问的这一个动作；</li><li><code>ApprovalPolicy = &#39;ask&#39; | &#39;never&#39;</code>——<code>never</code> 确定性返回 rejected（严格 headless/CI 姿态）；</li><li><code>ApprovalRequest</code> <strong>故意不含工具参数</strong>——answerer 用 <code>callId</code> 把提示贴到已流式到达的工具调用上，避免第二份会漂移的渲染副本；</li><li><code>request()</code> 要求 <strong>open turn</strong>——<code>approval/asked</code> + <code>approval/decided</code> 审计对必须被持久化日志的 turn 边界包住，turn 之间裸事件在 reload 时会被当 crash 尾巴丢弃；</li><li><code>decide()</code>：signal abort → <code>cancelled</code>；<strong><code>never</code> 策略在派发前就地判</strong>（即使 <code>prepend: true</code> 后挂的监听器也绕不开）；否则 <code>ctx.waterfall(scopeTarget(this, agent), &#39;approval/request&#39;, req, () =&gt; &#39;unavailable&#39;)</code>；throwing answerer 用 <code>unavailable</code> 关闭问题——<strong>绝不让 answerer 崩溃打开工具调用</strong>；</li><li>事件：<code>approval/request</code>（waterfall，按 agent 过滤）、<code>approval/asked</code>/<code>approval/decided</code>（emit 审计）、<code>approval/policy</code>（策略事件）。</li></ul><h3 id="tools-管线内的审批门" tabindex="-1">tools 管线内的审批门 <a class="header-anchor" href="#tools-管线内的审批门" aria-label="Permalink to &quot;tools 管线内的审批门&quot;">​</a></h3><p>审批不埋在个别工具里，而在 <code>ctx.tools</code> 的执行管线：</p><ul><li><code>tools/pre-execute</code>（waterfall）返回 <code>allow | deny | ask</code>；<strong><code>ask</code> 触发 <code>serviceAsk</code></strong>：机会式 <code>ctx.get(&#39;approval&#39;)</code>（没有则退化为 deny）→ <code>approval.request({ agent, toolName, callId, reason, signal })</code> → 结果映射（<code>allowed-once → allow</code>；<code>rejected/cancelled/unavailable →</code> 各自 deny reason，让模型区分&quot;人拒绝&quot;与&quot;无渠道&quot;）；</li><li>沙箱升级的审批<strong>独立接入</strong>（escalation 在工具内部、任何命令执行之前调 <code>ctx.approval.request</code>），不经过 tools/ask。</li></ul><h3 id="执行管道全景-tools-src-index-ts" tabindex="-1">执行管道全景（tools/src/index.ts） <a class="header-anchor" href="#执行管道全景-tools-src-index-ts" aria-label="Permalink to &quot;执行管道全景（tools/src/index.ts）&quot;">​</a></h3><p><code>createExecution</code>（冻结参数）→ <strong>pre-policy</strong>（<code>tools/pre-execute</code>，含 ask 门）→ <strong>单调守卫</strong>（<code>guard()</code>，后续监听者无法撤销）→ <strong>around-dispatch</strong>（<code>tools/execute</code> → <code>dispatchToolBody</code>）→ <strong>post-policy</strong>（<code>tools/post-execute</code>：<code>accept|block|replace</code>）→ 内容 finalize → 最终通知（<code>tools/result</code> emit，只读冻结结果）。</p><p><code>ToolExecution</code>（<code>exec</code>）携带 <code>rootCallId</code> + 不透明 <code>token</code> + <code>agent/callId/name/signal</code>，被<strong>原样</strong>当 actor 传给 <code>fs/*</code> 事件——fs 观察策略、审批都用 <code>exec.agent</code> 作 owner。这就是&quot;fs/* 事件只带不透明 object actor、政策插件结构性窄化&quot;的统一落点。</p><h2 id="_15-6-子进程-shell-终端" tabindex="-1">15.6 子进程 / shell / 终端 <a class="header-anchor" href="#_15-6-子进程-shell-终端" aria-label="Permalink to &quot;15.6 子进程 / shell / 终端&quot;">​</a></h2><ul><li><strong><code>ctx.subprocess</code></strong>：<code>spawn</code> 抽象（argv、cwd、env、stdio）；<code>subprocess-local</code> 直通；<code>subprocess-e2b</code> 远程。bash、PTY、LSP、子代理全部消费它；</li><li><strong><code>ctx.shell</code></strong>：<code>execute(command, opts)</code> 抽象；<code>bash-local</code>（裸）/<code>bash-sandbox</code>（沙箱包裹 argv）/<code>pwsh-local</code>；<code>tool-bash</code> 消费；</li><li><strong><code>ctx.terminals</code></strong>：持久终端（PTY 生命周期：create/attach/input/output/exit）；<code>terminal-bash</code> 实现，<code>tool-terminal</code> 消费——终端会话跨工具调用存活，是交互式工作流的基础。</li></ul><p><strong>沙箱如何包裹 argv（端到端）</strong>：<code>bash-sandbox</code> 把命令构造成 <code>[...runnerArgv, &#39;--&#39;, ...argv]</code>（bwrap/seatbelt 的 <code>--</code> 分隔符），runner 失败按 <code>fatalSignatures</code> 分类，denial 按方言签名识别并转成统一 <code>[sandbox: ...]</code> 标记喂给模型。</p><h2 id="_15-7-后台作业-ctx-jobs" tabindex="-1">15.7 后台作业：ctx.jobs <a class="header-anchor" href="#_15-7-后台作业-ctx-jobs" aria-label="Permalink to &quot;15.7 后台作业：ctx.jobs&quot;">​</a></h2><p><code>JobRegistry</code>（<code>packages/jobs/jobs</code>）：<code>start({ kind, label, owner, run })</code> 注册长任务；返回 <code>JobId</code>；配套通用控制工具 <code>job_kill</code>/<code>job_list</code>/<code>job_output</code>；完成经 <code>agent/*</code> 事件通知；<code>tool-bash</code> 的 <code>run_in_background</code> 与终端 <code>pty-send</code> 都走它。任务生命周期（发布后）归 <code>job_kill</code>/所有者销毁，不再归 <code>exec.signal</code>（第 19 章）。</p><blockquote><p><strong>事件纠错</strong>：不存在 <code>jobs/*</code> 事件——jobs 用 <code>onJobDone</code>/<code>onJobsChanged</code> 监听器而非 Cordis 事件；也不存在 <code>tool/start</code>、<code>tool/error</code> 事件——工具的生命周期事实就是会话事件 <code>tool/call</code> + <code>tool/result</code>（<code>tools/result</code> 是只读观察、<code>tools/change</code> 是注册表脏标记）。另外 <code>tool-fs</code> 的工具名是裸的 <code>read</code>/<code>write</code>/<code>edit</code>/<code>read_image</code>（没有 <code>ws_*</code> 前缀），且 write 路径不调 <code>ctx.fs.stat</code>——存在性检查由 fs provider 内部的 probe 守卫完成。</p></blockquote><h2 id="_15-8-其他接缝速览" tabindex="-1">15.8 其他接缝速览 <a class="header-anchor" href="#_15-8-其他接缝速览" aria-label="Permalink to &quot;15.8 其他接缝速览&quot;">​</a></h2><ul><li><strong><code>ctx.storage</code></strong>：键值存储 seam（<code>storage-json</code>/<code>storage-sqlite</code>），<code>storageDomain</code> 分域；</li><li><strong><code>ctx.attachments</code></strong>：附件引用（只读位图等，<code>ImageAttachmentRef</code>）；</li><li><strong><code>ctx.credentials</code></strong>：凭据 seam（<code>credentials-local</code>），LLM 适配器读取 API key；</li><li><strong><code>ctx.codeRuntime</code></strong>：Code Mode 的代码执行运行时（worker thread）。</li></ul><h2 id="_15-9-设计亮点小结" tabindex="-1">15.9 设计亮点小结 <a class="header-anchor" href="#_15-9-设计亮点小结" aria-label="Permalink to &quot;15.9 设计亮点小结&quot;">​</a></h2><ol><li><strong>一次 Provider 替换迁移整个产品</strong>：fs/subprocess 共享执行世界，指向远程沙箱则 Bash/PTY/LSP 全部随之迁移；</li><li><strong>策略随调用携带</strong>（per-call sandbox policy）而非固定在 provider；</li><li><strong>失败关闭</strong>：无沙箱后端 → <code>SandboxUnavailableError</code>；审批无渠道 → <code>unavailable</code>；<code>never</code> 策略派发前就地判；</li><li><strong>统一升级编舞</strong>：严格更宽阶梯执行期检查，审批与沙箱词汇单一来源；</li><li><strong>策略即持久化事件</strong>：<code>sandbox/mode</code>、<code>approval/policy</code>、<code>permission/preset</code> 都是可重放审计日志；</li><li><strong>不透明 actor</strong>：<code>fs/*</code> 事件带 <code>ToolExecution</code> 对象而非结构化身份，策略插件自行窄化；</li><li><strong>平台 runner 链 + 探测仲裁 + 方言识别</strong>：跨 Linux/macOS/Windows 统一沙箱语义。</li></ol><p>下一章：代理预设、目标与子代理。</p>',48)])])}const b=o(a,[["render",s]]);export{g as __pageData,b as default};
